const raw = items[0].json;
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;

if (!body || typeof body !== 'object') {
  throw new Error('Payload fehlt');
}
if (!Array.isArray(body.members)) {
  throw new Error('members muss ein Array sein');
}
if (!Array.isArray(body.fields)) {
  throw new Error('fields muss ein Array sein');
}

const requiredFields = ['insta', 'website', 'flyer'];
for (const f of requiredFields) {
  if (!body.fields.includes(f)) {
    throw new Error(`Feld ${f} fehlt in fields`);
  }
}

const asBool = (v) => {
  if (v === true || v === 1) return true;
  if (v === false || v === 0 || v == null) return false;
  const s = String(v).trim().toLowerCase();
  if (['ja', 'true', '1', 'yes'].includes(s)) return true;
  if (['nein', 'false', '0', 'no', ''].includes(s)) return false;
  return Boolean(v);
};

const members = body.members
  .filter((m) => m && typeof m === 'object')
  .map((m) => ({
    id: m.id,
    mitgliedsnummer: m.mitgliedsnummer ?? '',
    name: m.name ?? '',
    vorname: m.vorname ?? '',
    insta: asBool(m.insta),
    website: asBool(m.website),
    flyer: asBool(m.flyer),
  }))
  .filter((m) => m.insta || m.website || m.flyer);

const exportedAt = body.exported_at || new Date().toISOString();
const day = String(exportedAt).slice(0, 10);

const payload = {
  exported_at: exportedAt,
  source: body.source || 'openjverein',
  trigger: body.trigger || 'unknown',
  fields: body.fields,
  members,
};

const csvHeader = 'id,mitgliedsnummer,name,vorname,insta,website,flyer\n';
const esc = (s) => `"${String(s ?? '').replace(/"/g, '""')}"`;
const yn = (v) => (v ? 'Ja' : 'Nein');
const csvRows = members
  .map((m) =>
    [m.id, esc(m.mitgliedsnummer), esc(m.name), esc(m.vorname), yn(m.insta), yn(m.website), yn(m.flyer)].join(','),
  )
  .join('\n');

const meta = {
  last_sync_at: exportedAt,
  source: payload.source,
  trigger: payload.trigger,
  member_count: members.length,
};

const jsonName = 'einwilligungen.json';
const csvName = 'einwilligungen.csv';
const metaName = 'last-sync.json';
const jsonContent = JSON.stringify(payload, null, 2);
const csvContent = csvHeader + csvRows + (csvRows ? '\n' : '');
const metaContent = JSON.stringify(meta, null, 2);

// Binary for Google Drive Upload (inputDataFieldName = data / jsonFile / …)
const jsonFile = await this.helpers.prepareBinaryData(
  Buffer.from(jsonContent, 'utf8'),
  jsonName,
  'application/json',
);
const csvFile = await this.helpers.prepareBinaryData(
  Buffer.from(csvContent, 'utf8'),
  csvName,
  'text/csv',
);
const metaFile = await this.helpers.prepareBinaryData(
  Buffer.from(metaContent, 'utf8'),
  metaName,
  'application/json',
);

return [{
  json: {
    payload,
    meta,
    archiveDay: day,
    jsonName,
    csvName,
    metaName,
    jsonContent,
    csvContent,
    metaContent,
  },
  binary: {
    jsonFile,
    csvFile,
    metaFile,
  },
}];

const src = $('Validieren + CSV').first();
if (!src.binary || !src.binary.jsonFile) {
  throw new Error('Binary jsonFile fehlt — Validieren + CSV prüfen');
}
return [{
  json: {
    fileName: src.json.jsonName,
    archiveDay: src.json.archiveDay,
    member_count: src.json.payload.members.length,
    exported_at: src.json.payload.exported_at,
  },
  binary: { data: src.binary.jsonFile },
}];

